+// API keys and roles. A request carries `Authorization: Bearer <key>`; keys
+// live in the store as apiKeys: [{ key, name, role }].
+import { AppError } from "../errors.js";
+import { router } from "./router.js";
+
+// What a cook may do besides reading; managers may do everything.
+const cookCan = router([
+  ["POST", "/recipes/:id/cook", true],
+  ["POST", "/batches/:id/waste", true],
+  ["POST", "/temperatures", true],
+  ["POST", "/stocktakes/:id/counts", true],
+]);
+
+/** The apiKeys entry for the request's Bearer key; throws `unauthorized` without a known key. */
+export function authenticate(store, headers) {
+  const name = Object.keys(headers).find((h) => h.toLowerCase() === "authorization");
+  const m = name ? /^Bearer (.+)$/.exec(String(headers[name]).trim()) : null;
+  const found = m && (store.data.apiKeys ?? []).find((k) => k.key === m[1]);
+  if (!found) throw new AppError("unauthorized");
+  return found;
+}
+
+/** Throws `forbidden` unless the key's role may make this request. */
+export function authorize(apiKey, method, pathname) {
+  if (apiKey.role === "manager") return;
+  if (apiKey.role === "viewer" || apiKey.role === "cook") {
+    if (method === "GET" && pathname !== "/audit") return;
+    if (apiKey.role === "cook" && cookCan(method, pathname)) return;
+  }
+  throw new AppError("forbidden");
+}
