diff --git a/tests/auth.test.js b/tests/auth.test.js
new file mode 100644
index 0000000..aa89ca0
--- /dev/null
+++ b/tests/auth.test.js
@@ -0,0 +1,36 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { app, KEYS } from "./helpers.js";
+
+const as = (key) => ({ authorization: `Bearer ${key}` });
+
+test("no key or an unknown key is 401", async () => {
+  const { raw } = app();
+  const a = await raw({ path: "/items" });
+  assert.equal(a.status, 401);
+  assert.equal(a.body.error.code, "unauthorized");
+  assert.equal((await raw({ path: "/items", headers: as("nope") })).status, 401);
+});
+
+test("roles limit what a key may do", async () => {
+  const { raw } = app();
+  assert.equal((await raw({ path: "/items", headers: as(KEYS.viewer) })).status, 200);
+  const v = await raw({ method: "POST", path: "/recipes/1/cook", headers: as(KEYS.viewer), body: { portions: 1 } });
+  assert.equal(v.status, 403);
+  assert.equal(v.body.error.code, "forbidden");
+  assert.equal((await raw({ method: "POST", path: "/recipes/1/cook", headers: as(KEYS.cook), body: { portions: 1 } })).status, 200);
+  assert.equal((await raw({ method: "POST", path: "/orders", headers: as(KEYS.cook), body: {} })).status, 403);
+  assert.equal((await raw({ path: "/audit", headers: as(KEYS.cook) })).status, 403);
+});
+
+test("changes are audited, newest first, for managers", async () => {
+  const { raw } = app();
+  await raw({ method: "POST", path: "/recipes/1/cook", headers: as(KEYS.cook), body: { portions: 1 } });
+  await raw({ method: "POST", path: "/orders", headers: as(KEYS.cook), body: {} });
+  const log = (await raw({ path: "/audit", headers: as(KEYS.manager) })).body;
+  assert.deepEqual(log.map((e) => [e.keyName, e.method, e.path, e.status]), [
+    ["cook", "POST", "/orders", 403],
+    ["cook", "POST", "/recipes/1/cook", 200],
+  ]);
+  assert.equal(log[0].at, "2026-10-28T10:00:00.000Z");
+});
